import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AH stories, built with the shared `followUp` helper in FollowUpCasesAF.
extension FollowUpCases {
    static let batchAH: [CaseTemplate] = [
        pressedPills, boxUnderAnotherName, schoolZoneSpeeding, checkpointFlight, forgedLienRelease, keptDeposits,
        truckRaffle, shedFire, phonedInScript, patientsPills
    ]

    // MARK: - After the pills in the mail

    static let pressedPills = followUp(
        key: "story.followup.pressedPills", category: .drugs,
        headlines: ["Traffic Stop Turns Up 40 Blue Pills", "Driver From Mailed-Pills Case Charged Again"],
        law: "pwisd", spec: "Possessed with intent to sell or deliver fentanyl, a Schedule II controlled substance, in the form of 40 pressed tablets, on {DATE}.", ages: 21...45, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy stopped {D}'s car on {STREET} on {DATE} for a dead taillight. A K-9 alerted, and under the driver's seat the deputy found a sandwich bag of 40 blue tablets stamped M30, $1,300 in twenties, and a second phone. The lab found fentanyl. {DL} says the car was borrowed and the pills, money, and phone weren't {D.his}.",
        state: [E(.forensic, 3, "Lab Report", "40 tablets containing fentanyl, 4.1 grams in all."),
                E(.physical, 2, "Cash and Second Phone", "$1,300 in twenties folded in a rubber band, and a prepaid phone with dozens of texts asking for \"blues.\"", .search)],
        defense: [E(.document, 1, "Car Registration", "The car is registered to {DL}'s cousin.")],
        witnessRole: "Narcotics detective",
        exam: [.direct("What did the second phone show?", "\"Forty-one texts in two days asking for 'blues,' with prices. Some answered with a location.\""),
               .direct("Why does the amount matter?", "\"Forty pills packaged together, with cash in small bills and a phone used for orders, is a sale amount, not personal use.\""),
               .direct("Why was the car stopped?", "\"A deputy stopped it on {STREET} for a dead taillight. A K-9 alerted on the car during the stop.\""),
               .direct("What was found under the driver's seat?", "\"A sandwich bag of 40 blue tablets stamped M30, $1,300 in twenties folded in a rubber band, and a second, prepaid phone.\""),
               .direct("What did the lab find?", "\"That the tablets contained fentanyl, 4.1 grams in all. They are not genuine pharmaceutical tablets.\""),
               .direct("Why was the amount significant to you?", "\"Forty pills in one bag, with cash in small bills and a phone full of orders, is how a seller carries them. A user does not carry forty.\""),
                    .cross("The car belongs to {DL}'s cousin.", "\"It does. {DL} was the only one in it.\""),
               .cross("Did you find {DL}'s fingerprints on the bag?", "\"We didn't test it. The bag never went to the lab for prints.\""),
               .cross("{DL} was not the registered owner of the car?", "\"The car is registered to {DL}'s cousin. {DL} was driving it and was the only person inside.\""),
               .cross("You did not test the bag for prints?", "\"No. The bag never went to the lab for prints, and no one asked us to send it.\""),
               .cross("{DL}'s mother was saved in the phone as 'Mom'?", "\"She was. That is one reason we asked {DL} about the phone. The cousin was arrested later and said the phone was his.\"")],
        theory: ("{D} was driving with 40 fentanyl pills, sale cash, and an order phone under {D.his} seat.",
                 "{D} borrowed a car. The State never tied the bag or the phone to {D.him}."),
        allocution: "\"That car was my cousin's, because mine was in the shop, and I didn't look under the seat. I keep getting near this stuff. I need to get away from it. I'm sorry for the trouble, and I'll change who I ride with.\"",
        truths: ("The second phone's contacts included {DL}'s mother, saved as \"Mom.\"",
                 "The cousin who owned the car was arrested a month later with the same stamped pills and admitted the phone was his."),
        defendant: [.direct("Whose car is it?", "\"My cousin's. Mine was in the shop.\""),
               .direct("Did you know what was under the seat?", "\"No. I didn't know what was under the seat, and I never looked there.\""),
               .direct("What were you doing that night?", "\"Driving home from a friend's house. The deputy stopped me for a taillight, and I was calm because I had nothing to hide.\""),
               .direct("Had you ever seen the pills or the phone?", "\"No. I did not know there was a phone or a bag under the seat, and I never touched either one.\""),
               .direct("Why did the phone have 'Mom' in it?", "\"I do not know. I told the deputy I did not recognize the phone, and my cousin has said it was his.\""),
               .direct("Why did your cousin lend you his car?", "\"Mine was in the shop for a brake job, and he said I could use his until it was done.\""),
                    .cross("$1,300 in twenties and a phone, under the seat you were sitting on.", "\"I didn't look under the seat.\""),
               .cross("After the pills in the mail, you're near fentanyl again.", "\"I know how it looks.\""),
               .cross("You were the only person in the car.", "\"I was driving alone that night. I understand why that looks bad, and I understand why they stopped asking questions.\""),
               .cross("The prepaid phone had your mother saved as 'Mom.'", "\"I have thought about that. My cousin had my mother's number, and he may have saved it when he borrowed my phone.\""),
                    .cross("Your cousin was arrested a month later with the same pills.", "\"I did not know that until later. It does not explain why I was driving his car that night.\"")],
        openings: ("A deputy stopped {D}'s car for a dead taillight, a K-9 alerted, and under the driver's seat was a bag of 40 blue tablets stamped M30 that the lab found to contain fentanyl, $1,300 in twenties, and a second phone full of texts asking for 'blues.'", "The defense will say the car belongs to {D}'s cousin, {D} was borrowing it while {D.his} own was in the shop, and nothing ties the bag or the phone to {D}. The bag was never tested for prints."),
        closings: ("Forty fentanyl pills, $1,300 in small bills, and an order phone were under the seat {D} was sitting on, and {D} had already been here over {PRIOR} for pills in the mail.", "The cousin who owns the car was arrested a month later with the same pills and said the phone was his. The State must prove {D} knew what was under the seat and not merely that {D} was driving."),
        timeline: [(0, "Stop on {STREET} for a dead taillight; K-9 alert; search."), (12, "Lab confirms fentanyl.")],
        identified: "Arrested at the traffic stop.")

    static let boxUnderAnotherName = followUp(
        key: "story.followup.boxUnderAnotherName", category: .whiteCollar,
        headlines: ["Mailbox Rented With Stolen License", "Shipping Store Box Rented in Another Man's Name"],
        law: "identityTheft", spec: "Knowingly used the identifying information of {V}, a driver's license number and name, to rent a private mailbox, with intent to make financial use of it, on or about {DATE}.", ages: 21...45, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a private mailbox at a shipping store in {HOOD} was rented in the name of {V}, using a photocopy of {V}'s driver's license that {V} had reported lost. {V} learned of it when a collection notice for a credit card {V.he} never opened arrived at {V.his} home. The store's camera shows {D} renting the box and picking up mail from it three times.",
        state: [E(.video, 3, "Store Camera", "{D} at the counter on the rental date, and at the mailbox on three later days."),
                E(.document, 2, "Rental Agreement", "Signed \"{V}\" with a photocopy of {V}'s license. The signature doesn't match {V}'s.")],
        defense: [E(.statement, 1, "A Favor", "{DL} says a man asked {D.him} to rent the box and pick up mail, and gave {D.him} the license copy.")],
        witnessRole: "Financial crimes detective",
        exam: [.direct("What came to the box?", "\"Two credit cards in {V}'s name, a replacement debit card, and a bank statement. One card was used for $2,200 before it was stopped.\""),
               .direct("Who is on camera?", "\"{DL}, renting the box and picking up mail three times.\""),
               .direct("How did {V} learn about the mailbox?", "\"When a collection notice arrived at {V}'s home for a credit card {V.he} never opened. {V} had reported {V.his} driver's license lost earlier.\""),
               .direct("What was the rental agreement?", "\"A private mailbox rental at a shipping store signed with {V}'s name and a photocopy of {V}'s license. The signature does not match {V}'s.\""),
               .direct("What came to the mailbox?", "\"Two credit cards in {V}'s name, a replacement debit card, and a bank statement. One card was used for $2,200 before it was stopped.\""),
               .direct("What did the store camera show?", "\"{DL} at the counter on the rental date, and at the mailbox on three later days, picking up mail.\""),
               .cross("Did {DL} use the cards?", "\"I can't put the card use on {DL}. The box, yes.\""),
               .cross("Did you look for the man {DL} describes?", "\"{DL} gave a first name only.\""),
               .cross("{DL} gave a first name for the man who asked {D.him}?", "\"A first name only, and no number or address. I have not been able to find a man who fits that description.\""),
               .cross("A notebook in {DL}'s car had {V}'s information?", "\"It did. It listed {V}'s birth date and Social Security number. {DL} says the man gave {D.him} that to use at the counter.\""),
                    .cross("The notebook in {DL}'s car had {V}'s birth date?", "\"It did, and the Social Security number too. That is what made me think {DL} had been given the information on purpose.\"")],
        theory: ("{D} rented a mailbox with another person's license so credit cards in that name could be collected.",
                 "{D} ran an errand for someone else. The State hasn't proved {D.he} knew the license was stolen."),
        allocution: "\"A guy asked me to rent that box, and he said his ID was expired. He told me to sign the name on the license, and now I see what that was. I'm done running errands for people.\"",
        truths: ("A notebook in {DL}'s car listed {V}'s birth date and Social Security number.",
                 "A man arrested for a string of identity thefts admitted he paid {DL} to rent boxes and told {D.him} the licenses were his relatives'."),
        defendant: [.direct("Why did you rent the box?", "\"A guy asked me to. He said his ID was expired.\""),
               .direct("Did you sign {V}'s name?", "\"He told me to sign the name on the license.\""),
               .direct("Who asked you to rent the box?", "\"A guy I know from around. He said his ID was expired and he could not rent a box in his own name, and he offered to pay me.\""),
               .direct("What did he give you?", "\"A photocopy of a license and instructions to sign the name on it. He told me the license belonged to his relative.\""),
               .direct("How many times did you pick up mail?", "\"Three times. I took it to him each time. I never opened anything, and I never used any of the cards.\""),
               .direct("What was the notebook for?", "\"He wrote the information down for me so I would not forget it at the counter. I kept it in my car.\""),
               .cross("Signing someone else's name didn't strike you as wrong?", "\"It does now. I should have realized signing someone else's name was wrong.\""),
               .cross("After the box in the post office, another box.", "\"I know. I did not learn from the first one, and I can see now how it looks to the court.\""),
               .cross("You picked up mail addressed to someone else.", "\"I did, three times. The name on the box was not mine, and I told myself it was fine because he said it was his relative's.\""),
               .cross("The man gave you the license copy.", "\"He did, and I took it without looking closely. I should have asked why he needed me for that.\""),
                    .cross("You picked up three times.", "\"I did. Each time I took the mail straight to him, and I never opened anything.\"")],
        openings: ("A private mailbox at a shipping store was rented in {V}'s name with a photocopy of {V}'s lost driver's license, and credit cards in {V}'s name came to it. The store camera shows {D} renting it and picking up mail on three later days.", "The defense will say a man asked {D} to rent the box as a favor because his own ID had expired, and gave {D} the license copy. {D} did not use the cards and did not know the license was stolen."),
        closings: ("The signature does not match {V}'s, {V}'s birth date and Social Security number were in a notebook in {D}'s car, and {D} was back after {PRIOR}. Three pickups show {D} knew what the box was for.", "{D} ran an errand for a man who paid {D.him}, and the man was arrested for a string of identity thefts. The State must prove {D} knew the license was stolen when {D.he} signed {V}'s name."),
        timeline: [(0, "Box rented in {V}'s name."), (24, "Collection notice reaches {V}; {V} reports it.")],
        identified: "The store camera.",
        impact: "\"I've spent four months on the phone with banks and the credit bureaus, and my credit score dropped a hundred points. Someone rented a mailbox in my name with a copy of my lost license. I still don't know what else they opened.\"")

    // MARK: - After the crossing guard

    static let schoolZoneSpeeding = followUp(
        key: "story.followup.schoolZoneSpeeding", category: .traffic,
        headlines: ["Driver in Crossing Guard Case Clocked at 52 in School Zone", "Reckless Driving Charge Near Same Elementary School"],
        law: "recklessDriving", threshold: 4, spec: "Drove a vehicle carelessly and heedlessly in willful or wanton disregard of the rights or safety of others, at 52 miles per hour in a 25 mile-per-hour school zone near {PLACE.SCHOOL}, on {DATE}.", ages: 24...65, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy running radar outside {PLACE.SCHOOL} on {DATE} clocked {D}'s SUV at 52 miles per hour in the 25 zone during morning drop-off, passing a stopped bus. {DL} says the radar was wrong and {D.he} was going \"maybe 35.\"",
        state: [E(.document, 3, "Radar Log", "52 miles per hour at 7:41 a.m., with the calibration certificate current."),
                E(.video, 2, "Bus Stop-Arm Camera", "{D}'s SUV passes the bus as its stop arm swings out.")],
        defense: [E(.document, 1, "Speedometer Check", "A shop says {DL}'s speedometer reads 4 miles per hour fast.")],
        witnessRole: "Patrol deputy",
        exam: [.direct("Why were you at the school?", "\"Parents asked for patrols after the crossing guard was killed down the street.\""),
               .direct("What did you clock?", "\"Fifty-two in the twenty-five, at 7:41, with kids on the sidewalk.\""),
               .direct("What was the reason for the patrol?", "\"Parents asked for extra patrols outside the school after a crossing guard was killed down the street. I was running radar at morning drop-off.\""),
               .direct("What speed did the radar show?", "\"52 miles per hour in a 25 zone at 7:41 a.m. The radar's calibration certificate was current, and I tested it that morning.\""),
               .direct("What else did you observe?", "\"The SUV passed a stopped bus as its stop arm swung out. Children were on the sidewalk waiting to cross.\""),
               .direct("What does the bus camera show?", "\"The stop-arm camera shows {D.his} SUV passing the bus as the arm comes out, on the same stretch where the radar reading was taken.\""),
               .cross("Radar can catch the wrong car.", "\"It was the only car moving in that lane.\""),
               .cross("{DL} didn't hit anyone.", "\"Not this time. {D.He} didn't hit anyone, but that's mostly luck.\""),
               .cross("A shop says {DL}'s speedometer reads fast?", "\"It reads about four miles per hour fast, which would make {D.him} slower than {D.he} thought, not faster. It would not change what the radar measured.\""),
               .cross("Another parent's dash camera shows something, doesn't it?", "\"It shows {DL} swerving around a child on a bicycle at the corner. I did not see that myself.\""),
                    .cross("The speedometer reads fast, doesn't it?", "\"A shop says it reads four miles an hour fast, which would make {D.him} slower than {D.he} thought. It would not change what my radar measured.\"")],
        theory: ("Fifty-two in a school zone during drop-off, passing a bus, is reckless.", "{D} was speeding. That's a ticket, not reckless driving."),
        allocution: "\"I think I was going thirty-five, not fifty-two, and the arm wasn't out when I passed. I know there are children at that school, and I think about it every day. I'll take the bus route a different way.\"",
        truths: ("A second parent's dash camera showed {DL} swerve around a child on a bicycle at the corner.",
                 "The deputy's radar was later found to be pointed at a lane that included a delivery truck going the same speed."),
        defendant: [.direct("How fast were you going?", "\"Thirty-five, maybe. It certainly wasn't fifty-two.\""),
               .direct("Did you see the bus?", "\"The arm wasn't out when I passed.\""),
               .direct("What were you doing that morning?", "\"Dropping my own child at school and then hurrying to work. I was running late, and I did not want to be late again.\""),
               .direct("Did you see any children?", "\"I saw kids on the sidewalk, and one on a bicycle at the corner. I swerved to give the bike room, and that is when I realized I should slow down.\""),
               .direct("What did you see when you reached the school?", "\"A line of cars waiting for the drop-off, a bus with its lights on, and a lot of children on the sidewalk.\""),
               .direct("Why were you at the school at that hour?", "\"I was dropping off my daughter and then running to work. I was late, and I was in a hurry.\""),
                    .cross("That school. After what happened to the crossing guard.", "\"I know. I think about it every day.\""),
               .cross("You were late again, weren't you?", "\"I'm always running late, and that's why I hurried.\""),
               .cross("The radar says fifty-two.", "\"The radar may have picked up another car, or the delivery truck beside me. I do not trust a number I did not see.\""),
               .cross("A bus with its stop arm out was right there.", "\"I did not see the arm until I was already past it. I know that is no excuse.\""),
                    .cross("The limit is 25 in the zone.", "\"I know. I should have been going 25, and I was not.\"")],
        openings: ("A deputy running radar outside the school at morning drop-off clocked {D}'s SUV at 52 miles per hour in the 25 zone, passing a stopped bus as its stop arm swung out, with children on the sidewalk waiting to cross.", "The defense will say the radar was wrong and {D} was going maybe 35, that a shop found {D}'s speedometer reads fast, and that the stop arm was not out when {D} passed. A parent's camera also shows {D} swerving to protect a child."),
        closings: ("Fifty-two in a twenty-five, past a stopped bus with its arm swinging out, in front of a school where a crossing guard was recently killed. {D} had already been here over {PRIOR}, and was running late.", "Radar can catch the wrong lane, and a speedometer that reads fast cannot be trusted either way. The State must prove {D} drove fifty-two and not the delivery truck beside {D.him}."),
        timeline: [(0, "7:41 a.m.: radar at 52 in the school zone; stop.")],
        identified: "Stopped by the deputy at the scene.")

    static let checkpointFlight = followUp(
        key: "story.followup.checkpointFlight", category: .traffic,
        headlines: ["Driver Speeds Away From License Checkpoint", "Chase Ends in Ditch on Shiloh Road"],
        law: "fleeing", spec: "Operated a motor vehicle while fleeing a law enforcement officer in the lawful performance of duties, at more than 15 miles per hour over the limit and with reckless driving, on {DATE}.", ages: 24...65, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} turned around short of a license checkpoint on {STREET} on {DATE}. When a trooper followed with lights and siren, {DL} accelerated to 80 in a 45 for three miles before sliding into a ditch on Shiloh Road. {DL} says {D.he} panicked because {D.his} insurance had lapsed.",
        state: [E(.video, 3, "Dash Camera", "Three minutes of pursuit with lights and siren; 80 miles per hour on the trooper's radar."),
                E(.document, 2, "Insurance Record", "{DL}'s liability insurance lapsed two weeks before.")],
        defense: [E(.statement, 1, "Panic", "{DL} says {D.he} didn't think, and stopped as soon as the car left the road.")],
        witnessRole: "State Highway Patrol trooper",
        exam: [.direct("What happened at the checkpoint?", "\"{DL} made a U-turn a hundred yards short. I followed with lights and siren. {D.He} sped up.\""),
               .direct("How fast?", "\"Eighty in a forty-five, through two curves and past a church letting out.\""),
               .direct("What was the checkpoint?", "\"A license checkpoint on {STREET} set up by the Highway Patrol. Cars approaching it were being stopped and checked one at a time.\""),
               .direct("What did {DL} do?", "\"Made a U-turn about a hundred yards short of the checkpoint. I followed with lights and siren, and {D.he} sped up.\""),
               .direct("How long did the pursuit last?", "\"About three minutes and three miles. My radar read 80 miles per hour in a 45, through two curves and past a church that was letting out.\""),
               .direct("How did it end?", "\"{DL} lost control and slid into a ditch on Shiloh Road. I found an open bottle of vodka in the footwell after the crash.\""),
               .cross("{DL} stopped once the car went into the ditch.", "\"The ditch stopped {D.him}. {D.He} didn't stop until the car went into it.\""),
               .cross("Nobody was hurt.", "\"No. Luck is the only reason nobody was hurt.\""),
               .cross("{DL} pulled to the shoulder once, didn't {D.he}?", "\"My own report notes that {D.he} pulled to the shoulder once before the ditch. {D.He} restarted when a second car blocked the shoulder.\""),
               .cross("{DL}'s insurance had lapsed two weeks before?", "\"The insurance record says so. I did not know that when I turned on my lights, and {DL} told me later that is why {D.he} turned around.\""),
               .cross("No one was hurt?", "\"No one was hurt, and nothing was hit besides the ditch. That was luck, and I will not take credit for it.\""),
                    .cross("The trooper's lights did not come on right away?", "\"I understand the dash camera shows my lights failing for the first thirty seconds. I was behind {D.him} when I activated them again.\"")],
        theory: ("{D} ran from a trooper at 80 miles per hour past a church letting out.", "{D} panicked over lapsed insurance and stopped when {D.he} could."),
        allocution: "\"I didn't have insurance that day and I panicked when the trooper's lights came on. I just kept going, and I don't know why. I didn't see the church. I've been scared of police cars since that morning at the school. I know that's not an excuse.\"",
        truths: ("An open bottle of vodka was found in the footwell after the crash.",
                 "The trooper's own report notes {DL} pulled to the shoulder once before the ditch but restarted when a second car blocked the shoulder."),
        defendant: [.direct("Why did you turn around?", "\"I had no insurance, and I panicked, so I turned around.\""),
               .direct("Did you hear the siren?", "\"Yes. I just kept going. I don't know why.\""),
               .direct("When did you see the trooper behind you?", "\"Right after the turn. I saw the lights come on and I heard the siren, and I did not stop.\""),
               .direct("How fast were you going?", "\"Fast. I do not remember exactly. I knew I was going too fast, and I was more scared than I have ever been.\""),
               .direct("What happened at the ditch?", "\"The car slid on the curve and left the road. I stopped as soon as the car stopped, and I got out with my hands up.\""),
               .direct("What did the trooper do?", "\"He followed me with his lights on and called for help over the radio. I could see him in my mirror the whole way.\""),
               .direct("What happened when the car stopped?", "\"I got out with my hands up, and the trooper put me on the ground. I told him I had no insurance and I was scared.\""),
               .cross("Eighty past a church letting out.", "\"I didn't see the church.\""),
               .cross("You ran from the scene once before, too.", "\"That's not what happened that morning.\"", "\"That was different.\""),
               .cross("You did not stop for three miles.", "\"I did not. I wanted to, and I did not know how. I kept thinking it would be over if I went a little farther.\""),
               .cross("There was an open bottle of vodka in your footwell.", "\"It was in the car, and I had not been drinking that night. It was there from a friend, and I should have thrown it out.\""),
               .cross("You could have stopped when the lights came on, couldn't you?", "\"I could have, and I did not. I know that, and I have thought about it every day since the night I put the car in the ditch.\""),
               .cross("You accelerated after you saw the lights.", "\"I did. I pressed the gas instead of the brake, and I have regretted that every day since.\"")],
        openings: ("{D} made a U-turn a hundred yards short of a license checkpoint on {STREET}, and when a trooper followed with lights and siren, {D} accelerated to 80 in a 45 for three miles, past a church letting out, before sliding into a ditch.", "The defense will say {D} panicked because {D.his} insurance had lapsed two weeks earlier, had no plan to hurt anyone, and stopped as soon as the car left the road. {D} pulled to the shoulder once and restarted when a car blocked it."),
        closings: ("Three minutes of lights and siren, eighty in a forty-five, a church letting out, and an open bottle of vodka in the footwell. {D} had already been here over {PRIOR} and knew what a trooper's lights mean.", "A driver with a lapsed policy panicked, and when the shoulder was blocked {D} kept going until the car left the road. The State must prove {D} meant to flee and not merely to escape a ticket."),
        timeline: [(0, "U-turn short of the checkpoint; pursuit; car in the ditch on Shiloh Road.")],
        identified: "Arrested at the scene.")

    // MARK: - After the mobile home

    static let forgedLienRelease = followUp(
        key: "story.followup.forgedLienRelease", category: .whiteCollar,
        headlines: ["Truck Sold With Forged Lien Release", "Buyer Says Bank Still Holds Title to Truck"],
        law: "forgery", spec: "Falsely made a lien release, purporting to be from a bank, on the title to a pickup truck sold to {V}, with intent to defraud, on or about {DATE}.", ages: 35...66, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sold a 2016 pickup to {V} for $11,000 on {DATE}, with a lien release on the title that appeared to come from a credit union. When {V} went to register the truck, the DMV said the credit union still held the lien. The credit union says the release is not theirs: the signer retired two years ago, and the seal is the wrong design.",
        state: [E(.document, 3, "The Release", "A lien release on credit union letterhead signed by an officer who retired two years earlier, with an outdated seal."),
                E(.document, 2, "Loan Records", "{DL} still owes the credit union $8,400 on the truck.")],
        defense: [E(.statement, 1, "Paperwork From a Friend", "{DL} says a friend who used to work at a dealership \"handled the paperwork.\"")],
        witnessRole: "Financial crimes detective",
        exam: [.direct("How do you know the release is false?", "\"The officer who signed it retired in 2023, the seal is one they stopped using, and the credit union has no record of a payoff.\""),
               .direct("Who benefits?", "\"{DL}. {D.He} kept $11,000 and the credit union still has its lien.\""),
               .direct("How did the buyer discover the problem?", "\"{V} went to register the truck at the DMV and was told the credit union still held the lien. The release on the title had not been issued by the credit union.\""),
               .direct("What is wrong with the release?", "\"It is on credit union letterhead, signed by an officer who retired two years earlier, with a seal the credit union stopped using.\""),
               .direct("How much does {DL} still owe on the truck?", "\"$8,400 to the credit union. The loan is still in default, and the lien is still on the title.\""),
               .direct("What did you find on {DL}'s laptop?", "\"A template of the credit union's old letterhead. It was in a folder with files from the date of the sale.\""),
               .cross("Can you show {DL} made the document?", "\"I can show {D.he} handed it to the buyer.\""),
               .cross("The friend from the dealership?", "\"{DL} wouldn't give a name.\""),
               .cross("You cannot show {DL} typed the release?", "\"I can show {DL} handed it to the buyer along with the title. The template on the laptop is the closest I can come to who made it.\""),
               .cross("{V} got a title with a lien still on it?", "\"Yes. {V} paid $11,000 for a truck that the credit union still has a right to take back.\""),
                    .cross("The credit union says it never issued the release?", "\"That is right. The release on the title is not the credit union's, and the signing officer retired two years ago.\"")],
        theory: ("{D} sold a truck {D.he} still owed on, with a fake release, just like the mobile home.", "{D} relied on a friend's paperwork."),
        allocution: "\"A friend who used to do titles told me the lien release was handled, and I thought the loan was close to paid. I didn't look closely. I'm sorry to {V}, who paid eleven thousand dollars. I'll make {V} whole, and I have a payment plan worked out with the credit union.\"",
        truths: ("A template of the credit union's old letterhead was found on {DL}'s laptop.",
                 "The friend who handled the paperwork was charged with forging three other lien releases the same year."),
        defendant: [.direct("Where did the release come from?", "\"A friend who used to do titles. He said it was handled.\""),
               .direct("Did you know you still owed on the truck?", "\"I thought it was close to paid.\""),
               .direct("How did you sell the truck?", "\"I posted it online and a buyer came out. We agreed on $11,000 and I handed over the title with what I thought was a lien release.\""),
               .direct("What was the file on your laptop?", "\"I saved a letter from the credit union when I got the loan. I did not make a template, and I do not know how that folder got that file.\""),
               .direct("What did you tell {V} about the title?", "\"That it was clear. I handed over the title with the release attached and said everything was done.\""),
               .direct("How did the buyer find you?", "\"Through an online listing. We met at a gas station, and I handed over the title with the release attached.\""),
                    .cross("$8,400 is close to paid?", "\"I didn't look. I don't know how close the $8,400 is to being paid.\""),
               .cross("Another sale of something you didn't own free and clear.", "\"I know how that looks.\""),
               .cross("You kept the $11,000.", "\"I did, and I spent most of it on bills. I intended to pay off the credit union, and I did not get the chance.\""),
               .cross("The credit union says the release is not theirs.", "\"I did not know that. I trusted my friend, and I never called the credit union myself.\""),
                    .cross("You still owed $8,400 when you sold the truck.", "\"I did. I thought the amount was closer to paid off than it was.\"")],
        openings: ("{D} sold a 2016 pickup to {V} for $11,000 with a lien release on the title that appeared to come from a credit union. When {V} went to register the truck, the DMV said the credit union still held the lien, and {D} still owed $8,400.", "The defense will say a friend who used to work at a dealership handled the paperwork, and {D} believed the release was genuine and that the truck was nearly paid off. {D} did not make the document."),
        closings: ("The release was signed by an officer who retired two years earlier, on an old seal, and a template of the credit union's old letterhead was on {D}'s laptop. {D} had already been here over {PRIOR} for a sale of something {D.he} did not own free and clear.", "{D} relied on a friend's paperwork, and the friend was later charged with forging other releases. The State must prove {D} knew the release was forged when {D.he} handed it to {V}."),
        timeline: [(0, "{V} buys the truck for $11,000."), (9, "DMV refuses registration: lien still on title.")],
        identified: "{V} had the bill of sale signed by {DL}.",
        impact: "\"That was my work truck, and I paid eleven thousand dollars for it. I can't register it, I can't drive it legally, and I can't get my money back. I lost weeks of work, and I'm still paying on the loan I took out to buy it.\"")

    static let keptDeposits = followUp(
        key: "story.followup.keptDeposits", category: .whiteCollar,
        headlines: ["Property Manager Kept Tenants' Deposits, Owner Says", "Rental Deposits Never Reached Trust Account"],
        law: "embezzlement", spec: "Embezzled $6,750 in tenant security deposits entrusted to {D.him} as manager of rental houses owned by {V}, between six months before {DATE} and {DATE}.", ages: 35...66, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was hired by {V} to manage four rental houses in {HOOD}. North Carolina law requires security deposits to be held in a trust account. Over six months, {D.he} collected $6,750 in deposits from new tenants. None reached the trust account. Bank records show the money went into {D.his} personal account.",
        state: [E(.document, 3, "Bank Records", "Five deposits from tenants into {DL}'s personal account; the trust account was never opened.", .search),
                E(.document, 2, "Management Agreement", "{DL} agreed to hold deposits \"in a separate trust account as required by law.\"")],
        defense: [E(.statement, 1, "Owed Fees", "{DL} says {V} owed {D.him} management fees and {D.he} was \"holding\" the deposits against them.")],
        witnessRole: "Financial crimes detective",
        exam: [.direct("Where did the deposits go?", "\"Into {DL}'s personal checking. Then to {D.his} car loan and everyday spending.\""),
               .direct("Was a trust account ever opened?", "\"No bank in the county has one in {DL}'s name or the properties' names.\""),
               .direct("What was {DL}'s job for {V}?", "\"{DL} managed four rental houses in {HOOD}, collecting rent and deposits from tenants and handling repairs. The management agreement said deposits would be held in a separate trust account.\""),
               .direct("What does North Carolina law require?", "\"Security deposits must be held in a trust account at a bank licensed in the state. They cannot be mixed with the manager's own money or spent.\""),
               .direct("How much did {DL} collect?", "\"$6,750 in deposits from five new tenants over six months. None of it reached a trust account.\""),
               .direct("How did {V} find out?", "\"{V} noticed that a tenant who moved out asked for a deposit refund that could not be paid. When we checked the bank records, there was no trust account, and the money was in {DL}'s personal checking.\""),
               .cross("{V} owed {DL} fees.", "\"{V} disputes that. Either way, the deposits belong to the tenants.\""),
               .cross("Did {DL} try to hide it?", "\"{D.He} gave {V} monthly statements showing a trust balance that didn't exist.\""),
               .cross("{DL} planned to open the trust account, didn't {D.he}?", "\"That is what {D.he} says. {D.He} wrote a text to a friend that said, 'the deposits are float till the next sale,' which sounds like spending, not saving.\""),
               .cross("No tenant lost money in the end, did they?", "\"I do not know of any who did. That is because {V} covered the refunds after the discovery, not because the deposits were held.\""),
                    .cross("{V} reimbursed the tenants after the discovery?", "\"{V} did, out of {V.his} own pocket. {DL} never repaid any of it.\"")],
        theory: ("{D} took tenants' deposits that the law says belong in trust, and faked statements to cover it.", "{D} held money {D.he} believed {D.he} was owed."),
        allocution: "\"I hadn't set up the deposit account yet, and {V} owed me money, so I kept what the tenants paid. I was going to fix it, and I know that isn't how the law works. I'm paying back every tenant first. I owe them that, and I'm sorry.\"",
        truths: ("A text from {DL} to a friend: \"the deposits are float till the next sale.\"",
                 "{V} later admitted owing {DL} $5,000 in fees and settled the civil case."),
        defendant: [.direct("Why didn't the deposits go into trust?", "\"I hadn't set up the account yet, and {V} owed me.\""),
               .direct("What about the monthly statements?", "\"I was going to fix it.\""),
               .direct("What was your arrangement with {V}?", "\"I managed the four houses for a monthly fee and a share of the rents. {V} was supposed to pay my fees on the first of each month, and often {V} was late.\""),
               .direct("Why did the deposits go into your own account?", "\"I had not opened the trust account yet, and {V} owed me fees. I put the deposits in my checking account, meaning it to be for a short time, and then it went on for months while I put off setting up the trust account.\""),
               .direct("What did you spend the money on?", "\"Some of it went to my car loan and my regular bills. I thought of it as holding what {V} owed me, and I meant to replace it when {V} paid.\""),
               .direct("When did you plan to open the trust account?", "\"As soon as {V} paid what {V.he} owed me. I kept telling myself I would do it next month.\""),
                    .cross("You showed a trust balance that didn't exist.", "\"I know. The statements showed a trust balance that didn't exist, and I can't defend that.\""),
               .cross("Six months and five tenants.", "\"Yes, that's right. Five tenants paid deposits over those six months.\""),
               .cross("You told a friend the deposits were 'float till the next sale.'", "\"I said that. It was a bad way to talk, and it was true that I was using the money while I waited for {V} to pay.\""),
                    .cross("The law required a trust account from the first deposit.", "\"I know that now. I did not understand it at the time, and I should have asked someone.\""), .cross("You collected $6,750 from five tenants.", "\"I did, and I deposited it in my own checking account. I should not have.\"")],
        openings: ("{D} was hired by {V} to manage four rental houses, and North Carolina law requires security deposits to be held in a trust account. Over six months {D} collected $6,750 from five tenants, and none of it reached a trust account.", "The defense will say {V} owed {D} management fees, that {D} was holding the money against what {V} owed, and that {D} meant to open the account. {V} later admitted owing $5,000 and the civil case was settled."),
        closings: ("The deposits went into {D}'s personal checking and then to a car loan and everyday spending, and monthly statements showed a trust balance that never existed. {D} had come through this court before, over {PRIOR}.", "{V} owed {D} $5,000 in fees and {D} meant to open a trust account and repay what {D.he} used. The State must prove {D} meant to keep the deposits and not merely to hold them against a debt."),
        timeline: [(-180, "{DL} hired to manage four houses."), (0, "A tenant asks for a deposit back; {V} finds no trust account.")],
        identified: "{V} reviewed the bank records after a tenant moved out.",
        impact: "\"I had to pay back every one of my tenants out of my own pocket, because the deposits were never in the trust account. I trusted {DL} with all four houses and never checked the books. It cost me a great deal of money, and it cost me my peace of mind.\"")

    // MARK: - After the pancake breakfast

    static let truckRaffle = followUp(
        key: "story.followup.truckRaffle", category: .whiteCollar,
        headlines: ["Raffle for Pickup Truck Had No Truck", "Fire Department Raffle Organizer Charged"],
        law: "falsePretenses",
        spec: "Obtained $4,900 from people buying raffle tickets, including {V}, by falsely representing that a pickup truck would be raffled to benefit a volunteer fire department, on or about {DATE}.", victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sold $20 raffle tickets for a \"brand new pickup\" worth $48,000 to benefit a volunteer fire department, $4,900 worth by {DATE}. The fire chief says the department never authorized a raffle, and no truck was ever bought. {V} bought ten tickets.",
        state: [E(.document, 3, "Fire Chief's Letter", "The department never authorized a raffle and received nothing."),
                E(.document, 2, "Bank Records", "Ticket money deposited to {DL}'s account; no truck purchase.", .search)],
        defense: [E(.statement, 1, "A Truck on Order", "{DL} says a dealer was holding a truck and the deal fell through.")],
        witnessRole: "Financial crimes detective",
        exam: [.direct("Did any dealer hold a truck?", "\"I called all six dealers in the county. None had any deal with {DL}.\""),
               .direct("Where did the money go?", "\"{DL}'s checking account. Rent, a phone bill, and cash.\""),
               .direct("What was the raffle advertised as?", "\"A $20 ticket for a chance at a brand new pickup worth $48,000, to benefit a volunteer fire department. The flyers carried the department's name.\""),
               .direct("How much was collected?", "\"$4,900 in ticket sales by the date of the report, deposited to {DL}'s personal account. {V} bought tickets and gave us the flyer.\""),
               .direct("What did the fire chief say?", "\"That the department never authorized a raffle and received nothing from it. The chief had never heard of {DL}'s plan.\""),
               .direct("What did you learn from the dealers?", "\"I called all six dealers in the county. None had any deal with {DL} for a truck, and none was holding one.\""),
               .cross("{DL} may have meant to buy the truck later.", "\"With $4,900? The truck on the flyer was $48,000.\""),
               .cross("Was there ever a drawing?", "\"No. There was never a drawing, as far as I could ever tell.\""),
               .cross("A salesman later said he promised {DL} a truck at cost?", "\"He did, after the fact. He had quit without telling anyone, and he did not put anything in writing.\""),
                    .cross("Did {DL} give the money to anyone at the fire department?", "\"No. Not a dollar of it reached the department, and the chief says he never heard from {D.him}.\""), .cross("How many people bought tickets?", "\"About two hundred, by the stubs. {V} bought several, and gave us the flyer.\""),
                    .cross("{DL} never contacted the fire department about the raffle?", "\"No. The chief said he first heard of it from a flyer {V} brought him.\"")],
        theory: ("{D} used a fire department's name to sell tickets for a truck that never existed.", "{D} planned a raffle that fell apart."),
        allocution: "\"I had a dealer lined up for that truck, and it fell through. I was going to surprise the volunteers, and I wanted to make up for the shortfall. I should never have done another fundraiser. I'll pay it all back, and I'm sorry to everyone who bought a ticket.\"",
        truths: ("{DL} had printed the flyers the same week {D.he} was in court for the pancake breakfast.",
                 "A dealer's salesman later admitted he'd promised {DL} a truck at cost and then quit without telling anyone."),
        defendant: [.direct("Was there a truck?", "\"I had a dealer lined up. It fell through.\""),
               .direct("Did the fire department know?", "\"I was going to surprise them.\""),
               .direct("Why did you start the raffle?", "\"I wanted to help the fire department. They had lost a truck, and I thought a raffle for a new pickup would bring in money.\""),
               .direct("Where did the ticket money go?", "\"Into my checking account. I paid my rent and my phone bill and some cash expenses, and I meant to replace it once the truck was bought.\""),
               .direct("How did you plan to buy the truck?", "\"I thought I could put the ticket money down and borrow the rest. I did not work it out in detail.\""),
               .direct("How many tickets did you sell?", "\"About two hundred. I sold them at church suppers and outside the grocery store.\""),
               .cross("Without asking them? After the breakfast?", "\"I wanted to make up for that.\""),
               .cross("The money's gone.", "\"Most of it. The money's mostly gone, and I can't give it back right now.\""),
               .cross("You printed flyers using the department's name without asking.", "\"I did, and I know I should not have. I wanted to make up for the pancake breakfast, and I rushed.\""),
               .cross("No drawing was ever held.", "\"No. I kept waiting for the dealer to call back. I did not want to hold a drawing without a truck.\""),
                    .cross("You used the department's name on the flyer.", "\"I did, without asking. I told myself it was for a good cause and that they would not mind.\"")],
        openings: ("{D} sold $20 raffle tickets for a $48,000 pickup to benefit a volunteer fire department, $4,900 by {DATE}. The fire chief says the department never authorized a raffle, no truck was bought, and the ticket money went to {D}'s personal account.", "The defense will say {D} wanted to help the fire department, had a salesman promise a truck at cost, and planned to surprise the department. The deal fell through, and no drawing was held."),
        closings: ("Flyers carrying a fire department's name, $4,900 deposited to {D}'s account, six dealers with no deal, and no drawing. {D} had already been here over {PRIOR} for a pancake breakfast.", "{D} meant to help and had a salesman promise a truck. A raffle that fell apart is a failure, and the State must prove {D} never meant to buy the truck when {D.he} took the money."),
        timeline: [(-30, "Flyers go up; ticket sales begin."), (0, "Fire chief hears of it and calls deputies.")],
        identified: "The fire chief saw a flyer.",
        impact: "\"Ten tickets. I bought them for the firemen. They came to my house when my husband had his heart attack.\"")

    static let shedFire = followUp(
        key: "story.followup.shedFire", category: .whiteCollar,
        headlines: ["Insurance Claim for Burned Shed Listed Tools That Weren't There", "Fire Marshal: Shed Was Empty Before It Burned"],
        law: "insuranceFraud",
        spec: "Presented a false statement in support of a homeowner's insurance claim for $14,200 in tools and equipment said to be lost in a shed fire, on or about {DATE}.", victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a shed behind {D}'s house in {HOOD} burned on {DATE}. {DL} filed a claim for $14,200 in power tools, a riding mower, and a generator. The fire marshal found no tool remains, no mower frame, and no generator in the ashes. A neighbor's camera shows {DL} loading a mower onto a trailer two days earlier.",
        state: [E(.physical, 3, "Fire Scene", "No mower frame, engine block, or metal tool remains in the ashes, which a fire this size would leave.", .search),
                E(.video, 2, "Neighbor's Camera", "{D} loads a riding mower and boxes onto a trailer two days before the fire.")],
        defense: [E(.document, 1, "Receipts", "Receipts for some of the tools from years earlier.")],
        witnessRole: "Fire marshal",
        exam: [.direct("What did the ashes show?", "\"A riding mower leaves a steel frame and an engine block. There was nothing. Not a drill battery.\""),
               .direct("How did the fire start?", "\"Undetermined. I can't say it was set. I can say the shed was empty.\""),
               .direct("What was the claim?", "\"$14,200 for power tools, a riding mower and a generator said to have been destroyed when the shed behind {DL}'s house burned.\""),
               .direct("What did you find in the ashes?", "\"No mower frame, no engine block, and no metal tool remains. A fire that size leaves steel behind, and there was nothing.\""),
               .direct("What did the neighbor's camera show?", "\"{DL} loading a riding mower and several boxes onto a trailer two days before the fire.\""),
               .direct("What did you learn about the cause?", "\"The cause is undetermined. I cannot say it was set. I can say that the shed was empty of the items claimed.\""),
               .cross("Receipts show {DL} owned the tools.", "\"At some point. Not in that shed that night.\""),
               .cross("The mower on the trailer could have been for repair.", "\"There's no repair shop with a record of it.\""),
               .cross("Receipts show {DL} bought tools, don't they?", "\"For some of the tools, from years earlier. They show that {DL} owned them at some point, not that they were in the shed that night.\""),
               .cross("{DL}'s brother borrowed the mower?", "\"{DL}'s brother later said he borrowed the mower and tools the day before the fire and had them all along.\""),
                    .cross("The fire could have started by accident?", "\"It could have. The cause is undetermined, and I cannot say it was set. The question for me is the missing tools.\"")],
        theory: ("{D} emptied the shed and claimed $14,200 for what wasn't there.", "{D} owned the tools; the State can't say what burned."),
        allocution: "\"My tools and my mower were in that shed. I took the mower out for gas and brought it back before the fire. I don't know how fires work, and I don't know how it started. I'll withdraw the claim. I needed the money, and I'm sorry.\"",
        truths: ("The mower turned up for sale at a pawn shop under {DL}'s name the week after the fire.",
                 "{DL}'s brother had borrowed the mower and tools the day before the fire and had them all along."),
        defendant: [.direct("What was in the shed?", "\"My tools and my mower.\""),
               .direct("The mower on the trailer?", "\"I took it out for gas and brought it back.\""),
               .direct("What happened the night of the fire?", "\"I was home and smelled smoke. I called the fire department, and the shed was already gone.\""),
               .direct("How did you come up with $14,200?", "\"I added up what I thought everything cost. I did not have all the receipts, and I guessed on some of the prices.\""),
               .direct("Where were you when the shed burned?", "\"At home, in the house, when I smelled smoke. I called the fire department and stood in the yard.\""),
               .direct("Why do you say the shed held $14,200 of tools?", "\"I added up the tools I had bought over the years. I had a mower, power tools, a generator and a lot of hand tools.\""),
                    .cross("Then where is the frame?", "\"I don't know how fires work.\""),
               .cross("Another time money came in for something that wasn't real.", "\"That's not fair. That was a different situation, and I don't think it should be compared.\""),
               .cross("No mower frame was found in the ashes.", "\"I do not know how fires work. I know it was a big fire, and I do not know what survives one.\""),
               .cross("The mower turned up at a pawn shop under your name.", "\"My brother had borrowed it, and I did not know he had pawned it. Whoever put it there, it was not me.\""),
               .cross("The fire marshal found no tool remains.", "\"I do not know how that is possible. I know what I had in that shed.\""),
                    .cross("The pawn shop had the mower under your name the week after.", "\"My brother must have pawned it with my ID. I did not know.\"")],
        openings: ("A shed behind {D}'s house burned, {D} filed a $14,200 claim for power tools, a riding mower and a generator, and the fire marshal found no mower frame, engine block or metal tool in the ashes. A neighbor's camera shows {D} loading a mower onto a trailer two days earlier.", "The defense will say {D} owned the tools and the mower, kept them in the shed, and that the State cannot say what burned. {D}'s brother had borrowed the mower and tools the day before."),
        closings: ("A fire this size leaves steel, and the shed held none. The mower was on a trailer two days before and at a pawn shop under {D}'s name the week after, and {D} had faced this court before, over {PRIOR}.", "{D} owned the tools, and the cause of the fire is undetermined. {D}'s brother had the mower all along, and the State must prove {D} claimed items that were not in the shed."),
        timeline: [(-2, "Neighbor's camera: mower and boxes loaded onto a trailer."), (0, "Shed fire."), (5, "Claim filed for $14,200.")],
        identified: "The insurer's investigator and the fire marshal.")

    // MARK: - After the prescription pad

    static let phonedInScript = followUp(
        key: "story.followup.phonedInScript", category: .drugs,
        headlines: ["Caller Posed as Doctor's Office to Order Painkillers", "Pharmacist Recognized Voice on Phoned-In Script"],
        law: "prescriptionFraud", spec: "Attempted to obtain oxycodone by fraud, by telephoning a pharmacy and falsely representing that the call came from a physician's office, on {DATE}.", ages: 23...45, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a caller to {PHARM} on {DATE}, identifying as a nurse at an orthopedic practice, phoned in 20 oxycodone tablets for a patient. The pharmacist called the practice back at its listed number; no one there had called. When {D} came to pick up the prescription under the patient's name, deputies were waiting.",
        state: [E(.digital, 3, "Pharmacy Call Log", "The call came from a prepaid number found in {DL}'s phone contacts under \"work.\""),
                E(.video, 2, "Pharmacy Camera", "{D} at the counter asking for the prescription in another person's name.")],
        defense: [E(.statement, 1, "Picking Up for a Friend", "{DL} says a friend asked {D.him} to pick up the friend's prescription.")],
        witnessRole: "Narcotics detective",
        exam: [.direct("How did the pharmacist catch it?", "\"Called the practice back on the number in the directory. No nurse there had called.\""),
               .direct("Who made the call?", "\"A prepaid number saved in {DL}'s phone as 'work.'\""),
               .direct("What was the call to the pharmacy?", "\"A caller identifying as a nurse at an orthopedic practice phoned in a prescription for 20 oxycodone tablets for a patient.\""),
               .direct("Where did the call come from?", "\"A prepaid number saved in {DL}'s phone contacts under 'work.' The prepaid phone itself was later found in {DL}'s car, with the pharmacy's number in its call history.\""),
               .direct("What did the pharmacy camera show?", "\"{DL} at the counter asking for the prescription in another person's name.\""),
               .direct("What did the pharmacist's notes record?", "\"The time of the call, the caller's name and callback number, and the quantity of 20 tablets. She wrote down that the voice sounded rehearsed.\""),
                    .cross("You don't have a recording of the call.", "\"No. I don't have a recording of the call, only my notes from afterward.\""),
               .cross("Is the patient real?", "\"No. The patient doesn't exist. Nobody at the practice had ever seen anyone by that name.\""),
               .cross("You have no recording of the call, do you?", "\"No. I have the pharmacist's notes and the call log. I do not have an audio recording.\""),
               .cross("The patient on the prescription does not exist?", "\"Right. Nobody at the practice had ever seen anyone by that name.\""),
               .cross("A former coworker admitted making the call?", "\"{DL}'s former coworker from the dental office later admitted it and said he sent {DL} to pick it up.\""),
                    .cross("The prepaid phone was in {DL}'s car, wasn't it?", "\"It was, with the pharmacy's number in its call history. {DL} says {D.he} found it there.\"")],
        theory: ("{D} called in a fake prescription and came to pick it up.", "{D} picked up a friend's medicine."),
        allocution: "\"A friend asked me to pick it up, saying it was for her mother. I don't know why I agreed. I've been in treatment since, and I relapsed and did something stupid. I'm sorry to the pharmacist and to my family. I'll go back to treatment today.\"",
        truths: ("The prepaid phone was in {DL}'s car, with the pharmacy's number in its call history.",
                 "{DL}'s former coworker from the dental office admitted making the call and sending {DL} to pick it up."),
        defendant: [.direct("Who asked you to pick it up?", "\"A friend. It was supposed to be for her mother.\""),
               .direct("Did you make the call?", "\"No. I didn't make the call, and I don't know who did.\""),
               .direct("Why did you go to the pharmacy?", "\"A friend asked me to pick up a prescription for her mother. She said she was working and could not get there.\""),
               .direct("Did you know the prescription was phoned in?", "\"I knew it was waiting at the counter. I did not know who had called it in or what it was for.\""),
               .direct("What about the prepaid phone?", "\"I found it in my car and did not know whose it was. I saved the number under 'work' because it had been there a while, and I thought it was my coworker's.\""),
               .direct("Who is your former coworker?", "\"A man I worked with at the dental office. He called me and asked me to pick it up, and I thought it was for his mother.\""),
               .cross("The number is in your phone as 'work.'", "\"I don't know why. I never saved it under that name.\""),
               .cross("After your last case, another fake prescription.", "\"I know. I'm back here after my last case, and I'm ashamed of that.\""),
               .cross("The patient does not exist.", "\"I did not know that. I thought it was for a woman's mother, and I never saw a name on it.\""),
               .cross("The prepaid phone in your car had the pharmacy's number in it.", "\"I found that phone in my car and did not know it was used for that. I should have turned it in.\""),
                    .cross("You went to the counter and asked for the prescription.", "\"I did, as a favor to my friend. I did not know anything about a phone call.\"")],
        openings: ("A caller who said she was a nurse at an orthopedic practice phoned in 20 oxycodone tablets for a patient. The pharmacist called the practice back and no one had called, and the number traced to a prepaid phone saved in {D}'s contacts as 'work.'", "The defense will say a friend asked {D} to pick up medicine for her mother, and {D} did not make the call or know the prescription was fake. {D}'s former coworker later admitted making it."),
        closings: ("The call came from a number saved in {D}'s phone as 'work,' the prepaid phone was in {D}'s car, the patient does not exist, and the camera shows {D} at the counter. This was not {D}'s first case here, since {PRIOR} came first.", "A former coworker admitted making the call and sending {D} to pick it up. The State must prove {D} knew the prescription was fake, and a friend's errand is not a crime."),
        timeline: [(0, "Phoned-in script; pharmacist calls the practice back; deputies wait at pickup.")],
        identified: "Arrested at the pharmacy counter.",
        extras: ["PHARM": ["Harbor Mart Pharmacy", "Main Street Drug", "Bayard Family Pharmacy"]])

    static let patientsPills = followUp(
        key: "story.followup.patientsPills", category: .whiteCollar,
        headlines: ["Home Health Aide Charged With Taking Patient's Pain Pills", "Pill Counts Came Up Short After Aide's Visits"],
        law: "exploitationElder", spec: "Knowingly took the property of {V}, an older adult in {D.his} care, by deception, oxycodone prescribed to {V}, between two months before {DATE} and {DATE}.", ages: 23...45, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} worked as a home health aide for {V}, 84, who takes oxycodone after hip surgery. {V}'s daughter began counting the pills and found the count short after each of {DL}'s visits, about 40 tablets over two months. A pill-bottle camera the daughter installed recorded {DL} taking tablets on {DATE}.",
        state: [E(.video, 3, "Bottle Camera", "{D} opens {V}'s pill bottle, takes several tablets, and puts them in a pocket."),
                E(.document, 2, "Pill Counts", "The daughter's log of counts before and after each visit.")],
        defense: [E(.statement, 1, "Dropped Pills", "{DL} says {D.he} was picking up pills {V} had dropped.")],
        witnessRole: "Sheriff's investigator",
        exam: [.direct("What did the counts show?", "\"Short after every visit by {DL}, and never after the other aide's.\""),
               .direct("What does the camera show?", "\"{DL} opening the bottle, taking tablets, and pocketing them.\""),
               .direct("Who is {V}?", "\"An 84-year-old woman who takes oxycodone after hip surgery. {V}'s daughter keeps a log of the counts of {V.his} pills.\""),
               .direct("What was found when {DL} was arrested?", "\"Four tablets in {D.his} pocket. They matched the strength and markings of {V}'s prescription.\""),
               .direct("How did the daughter first notice the missing pills?", "\"She counted the bottle each evening after getting {V} settled. Three nights in a row the count was lower after a visit by {DL}.\""),
               .direct("What did {DL} say when you arrested {D.him}?", "\"{D.He} said {D.he} was putting pills back in the bottle. {D.He} did not say anything else.\""),
                    .cross("{V} drops pills sometimes.", "\"The daughter checks the floor every night. That's how she started counting.\""),
               .cross("Did you find pills on {DL}?", "\"Four in {D.his} pocket when we arrested {D.him}.\""),
               .cross("The other aide was also caught on camera?", "\"Later, yes. The other aide was caught on the same camera taking pills, and the count gap followed her shifts after that.\""),
               .cross("{DL} is in treatment now?", "\"{DL} says so. I do not know about that, and it does not change what the camera recorded.\""),
                    .cross("{DL} was upset when you arrested {D.him}?", "\"{D.He} was crying. {D.He} told us {D.he} was sorry, and that {D.he} was in treatment.\"")],
        theory: ("{D} took an 84-year-old's pain medicine, a few pills at a time.", "{D} was picking up pills from the floor."),
        allocution: "\"I was putting back pills that {V} dropped, and I was going to put them in the bottle. It looks that way, and I know it. I'm an addict, and I took from someone who trusted me. I'm so sorry, {VL}.\"",
        truths: ("A text from {DL} the same week: \"got 10 more from the old lady.\"",
                 "The other aide was later caught on the same camera taking pills, and the count gap followed her shifts."),
        defendant: [.direct("What were you doing with the bottle?", "\"Putting back pills {V} dropped.\""),
               .direct("Why were pills in your pocket?", "\"I was going to put them in the bottle.\""),
               .direct("What was your job with {V}?", "\"I was a home health aide. I helped {V} with meals, bathing and getting around, and I gave {V.him} the medicine {V.he} was supposed to take.\""),
               .direct("Have you struggled with pills yourself?", "\"I have, and I am in treatment now. I am not proud of it, and I know it makes people doubt me.\""),
               .direct("How did you feel while you were caring for {V}?", "\"I felt guilty and sick, and I was not in a good place. I liked {V}, and I did not want to hurt {V.him}.\""), .direct("Where are you now?", "\"In treatment, and I have been clean for months. I want to tell {V}'s family I am sorry.\""),
                    .cross("The camera shows you taking them out.", "\"It looks that way. The camera shows me taking them out, and I can't argue with video.\""),
               .cross("Another case with oxycodone that wasn't yours.", "\"I'm in treatment now. I know it's another case with oxycodone that wasn't mine.\""),
               .cross("The count was short after every visit of yours.", "\"I do not know how that happened. I did not count the pills, and I did not know the daughter was counting.\""),
                    .cross("The count was short after each of your visits and no one else's.", "\"I cannot explain that. I know what the numbers say, and I cannot argue with them.\""), .cross("You took a vulnerable woman's pain medicine.", "\"I did, and I am ashamed of it. I would give anything to undo it.\"")],
        openings: ("{D} worked as a home health aide for {V}, 84, who takes oxycodone after hip surgery. {V}'s daughter found the count short after each of {D}'s visits, about 40 tablets in two months, and a bottle camera shows {D} taking tablets and pocketing them.", "The defense will say {D} was picking up pills {V} had dropped and putting them back, and the camera does not show where they went. The other aide was later caught on the same camera."),
        closings: ("Forty tablets short in two months, short after every visit of {D}'s and never after the other aide's, and four tablets in {D}'s pocket on arrest. {D} already knew this courtroom from {PRIOR}.", "The camera shows {D} with the bottle, and {V} drops pills. The other aide was later caught taking pills, and the State must prove {D} took them for {D.himself} and not to put them back."),
        timeline: [(-60, "{DL} begins visits."), (-30, "Daughter starts counting pills."), (0, "Bottle camera records {DL}; arrest.")],
